# ------------------------------------------------------------

print("\nLabel distribution:")

distribution = (
    model_df["label"]
    .value_counts()
    .sort_index()
    .to_frame("Count")
)

distribution["Percentage"] = (
    distribution["Count"] /
    len(model_df) * 100
).round(2)

display(distribution)

# ------------------------------------------------------------
