import os
import sys
import json
import platform
import subprocess
import pandas as pd
import torch
import transformers
import numpy
import pandas

# ------------------------------------------------------------
# 1. Locate best/latest AfroXLM-R checkpoint
# ------------------------------------------------------------

model_dir = "/content/afroxlmr_intention_detection"

checkpoint_dirs = []

if os.path.exists(model_dir):

    for name in os.listdir(model_dir):

        path = os.path.join(model_dir, name)

        if (
            os.path.isdir(path)
            and name.startswith("checkpoint-")
            and name.split("-")[-1].isdigit()
        ):
            checkpoint_dirs.append(path)

if checkpoint_dirs:

    checkpoint_dirs = sorted(
        checkpoint_dirs,
        key=lambda x: int(
            os.path.basename(x).split("-")[-1]
        )
    )

    checkpoint_path = checkpoint_dirs[-1]

else:

    checkpoint_path = model_dir

print("Selected checkpoint:")
print(checkpoint_path)

# ------------------------------------------------------------
# 2. Read TrainerState
# ------------------------------------------------------------

trainer_state_path = os.path.join(
    checkpoint_path,
    "trainer_state.json"
)

trainer_state = {}

if os.path.exists(trainer_state_path):

    with open(
        trainer_state_path,
        "r",
        encoding="utf-8"
    ) as f:

        trainer_state = json.load(f)

# ------------------------------------------------------------
# 3. Read training arguments
# ------------------------------------------------------------

training_args_path = os.path.join(
    checkpoint_path,
    "training_args.bin"
)

training_args = None

if os.path.exists(training_args_path):

    try:

        training_args = torch.load(
            training_args_path,
            map_location="cpu",
            weights_only=False
        )

    except Exception as e:

        print(
            "Could not directly load training_args.bin:",
            e
        )

# ------------------------------------------------------------
# 4. Read model configuration
# ------------------------------------------------------------

config_path = os.path.join(
    checkpoint_path,
    "config.json"
)

model_config = {}

if os.path.exists(config_path):

    with open(
        config_path,
        "r",
        encoding="utf-8"
    ) as f:

        model_config = json.load(f)

# ------------------------------------------------------------
# 5. Helper function
# ------------------------------------------------------------

def get_training_arg(name, default="Not recorded"):

    if training_args is not None:

        try:
            value = getattr(
                training_args,
                name
            )

            if value is not None:
                return value

        except Exception:
            pass

    return default

# ------------------------------------------------------------
# 6. GPU information
# ------------------------------------------------------------

if torch.cuda.is_available():

    gpu_name = torch.cuda.get_device_name(0)

    cuda_version = torch.version.cuda

    gpu_count = torch.cuda.device_count()

else:

    gpu_name = "CPU"

    cuda_version = "Not available"

    gpu_count = 0

# ------------------------------------------------------------
