# ============================================================
# CELL 30: REPRODUCIBILITY AND EXPERIMENTAL CONFIGURATION
# ============================================================

import os
import sys
import json
import platform
import random
import numpy as np
import pandas as pd
import torch

# ------------------------------------------------------------
# 1. BASIC ENVIRONMENT
# ------------------------------------------------------------

print("=" * 80)
print("REPRODUCIBILITY AND EXPERIMENTAL CONFIGURATION")
print("=" * 80)

environment = {}

environment["Python"] = sys.version.split()[0]
environment["Operating System"] = platform.platform()
environment["PyTorch"] = torch.__version__
environment["NumPy"] = np.__version__
environment["Pandas"] = pd.__version__

try:
    import transformers
    environment["Transformers"] = transformers.__version__
except Exception:
    environment["Transformers"] = "Not available"

try:
    import sklearn
    environment["Scikit-learn"] = sklearn.__version__
except Exception:
    environment["Scikit-learn"] = "Not available"

try:
    import statsmodels
    environment["Statsmodels"] = statsmodels.__version__
except Exception:
    environment["Statsmodels"] = "Not available"


# ------------------------------------------------------------
# 2. HARDWARE
# ------------------------------------------------------------

if torch.cuda.is_available():

    environment["Device"] = "CUDA"
    environment["GPU"] = torch.cuda.get_device_name(0)
    environment["CUDA"] = torch.version.cuda

    gpu_memory = (
        torch.cuda.get_device_properties(0).total_memory
        / (1024 ** 3)
    )

    environment["GPU Memory (GB)"] = round(
        gpu_memory,
        2
    )

else:

    environment["Device"] = "CPU"
    environment["GPU"] = "Not available"
    environment["CUDA"] = "Not available"
    environment["GPU Memory (GB)"] = "Not available"


# ------------------------------------------------------------
# 3. RANDOM SEED
# ------------------------------------------------------------

SEED = 42

random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)

if torch.cuda.is_available():
    torch.cuda.manual_seed_all(SEED)

environment["Random Seed"] = SEED


# ------------------------------------------------------------
# 4. VERIFIED EXPERIMENTAL SETTINGS
# ------------------------------------------------------------

configuration = {

    "Model": "AfroXLM-R",

    "Number of classes": 9,

    "Epochs": 10,

    "Learning rate": 2e-5,

    "Batch size": 16,

    "Weight decay": 0.01,

    "Maximum sequence length": 128,

    "Random seed": 42,

    "Padding": "Dynamic padding",

    "Model selection criterion":
        "Best validation Macro-F1",

    "Test set usage":
        "Used only for final evaluation",

    "Early stopping":
        "Disabled",

    "Mixed precision":
        "FP16 when CUDA is available"
}


# ------------------------------------------------------------
# 5. TRY TO READ SAVED CHECKPOINT CONFIGURATION
# ------------------------------------------------------------

checkpoint_candidates = [
    "/content/afroxlmr_intention_detection/checkpoint-4980",
    "/content/afroxlmr_intention_detection/checkpoint-4482"
]

checkpoint_path = None

for path in checkpoint_candidates:

    if os.path.exists(path):

        checkpoint_path = path
        break


saved_model_config = {}

if checkpoint_path is not None:

    config_path = os.path.join(
        checkpoint_path,
        "config.json"
    )

    training_args_path = os.path.join(
        checkpoint_path,
        "training_args.bin"
    )

    # --------------------------------------------------------
    # Read model config
    # --------------------------------------------------------

    if os.path.exists(config_path):

        try:

            with open(
                config_path,
                "r",
                encoding="utf-8"
            ) as f:

                saved_model_config = json.load(f)

        except Exception as e:

            print(
                f"\nCould not read config.json: {e}"
            )


    # --------------------------------------------------------
    # Read training arguments if available
    # --------------------------------------------------------

    if os.path.exists(training_args_path):

        try:

            import torch

            training_args = torch.load(
                training_args_path,
                map_location="cpu",
                weights_only=False
            )

            if hasattr(
                training_args,
                "learning_rate"
            ):
                configuration[
                    "Saved learning rate"
                ] = training_args.learning_rate

            if hasattr(
                training_args,
                "per_device_train_batch_size"
            ):
                configuration[
                    "Saved training batch size"
                ] = (
                    training_args
                    .per_device_train_batch_size
                )

            if hasattr(
                training_args,
                "num_train_epochs"
            ):
                configuration[
                    "Saved epochs"
                ] = (
                    training_args
                    .num_train_epochs
                )

            if hasattr(
                training_args,
                "weight_decay"
            ):
                configuration[
                    "Saved weight decay"
                ] = (
                    training_args
                    .weight_decay
                )

            if hasattr(
                training_args,
                "seed"
            ):
                configuration[
                    "Saved random seed"
                ] = training_args.seed

            if hasattr(
                training_args,
                "fp16"
            ):
                configuration[
                    "Saved FP16"
                ] = training_args.fp16

        except Exception as e:

            print(
                f"\nTraining arguments could not be read: {e}"
            )


# ------------------------------------------------------------
