def calculate_unk_rate_bilstm(token_lists):
    total_tokens = sum(len(x) for x in token_lists)

    unknown_tokens = sum(
        1
        for tokens in token_lists
        for token in tokens
        if token not in word2id_bilstm
    )

    return (
        unknown_tokens / total_tokens
        if total_tokens > 0
        else 0.0
    )

