# ============================================================
# BiLSTM INTENTION DETECTION
# CELL 8: TRAINING AND VALIDATION FUNCTIONS
# ============================================================

import numpy as np
from sklearn.metrics import (
    accuracy_score,
    precision_recall_fscore_support
)

print("=" * 80)
print("BiLSTM — TRAINING AND VALIDATION FUNCTIONS")
print("=" * 80)


def train_one_epoch_bilstm(
    model,
    dataloader,
    criterion,
    optimizer,
    device
):
    model.train()

    total_loss = 0.0
    all_predictions = []
    all_labels = []

    for batch in dataloader:

        input_ids = batch["input_ids"].to(device)
        attention_mask = batch["attention_mask"].to(device)
        labels = batch["labels"].to(device)

        optimizer.zero_grad(set_to_none=True)

        logits = model(
            input_ids,
            attention_mask
        )

        loss = criterion(
            logits,
            labels
        )

        loss.backward()

        # Gradient clipping for stable BiLSTM training
        torch.nn.utils.clip_grad_norm_(
            model.parameters(),
            max_norm=1.0
        )

        optimizer.step()

        total_loss += (
            loss.item() * labels.size(0)
        )

        predictions = torch.argmax(
            logits,
            dim=1
        )

        all_predictions.extend(
            predictions.detach().cpu().numpy()
        )

        all_labels.extend(
            labels.detach().cpu().numpy()
        )

    average_loss = total_loss / len(dataloader.dataset)

    accuracy = accuracy_score(
        all_labels,
        all_predictions
    )

    precision, recall, f1, _ = (
        precision_recall_fscore_support(
            all_labels,
            all_predictions,
            average="macro",
            zero_division=0
        )
    )

    return {
        "loss": average_loss,
        "accuracy": accuracy,
        "macro_precision": precision,
        "macro_recall": recall,
        "macro_f1": f1
    }


def evaluate_bilstm(
    model,
    dataloader,
    criterion,
    device
):
    model.eval()

    total_loss = 0.0
    all_predictions = []
    all_labels = []

    with torch.no_grad():

        for batch in dataloader:

            input_ids = batch["input_ids"].to(device)
            attention_mask = batch["attention_mask"].to(device)
            labels = batch["labels"].to(device)

            logits = model(
                input_ids,
                attention_mask
            )

            loss = criterion(
                logits,
                labels
            )

            total_loss += (
                loss.item() * labels.size(0)
            )

            predictions = torch.argmax(
                logits,
                dim=1
            )

            all_predictions.extend(
                predictions.cpu().numpy()
            )

            all_labels.extend(
                labels.cpu().numpy()
            )

    average_loss = total_loss / len(dataloader.dataset)

    accuracy = accuracy_score(
        all_labels,
        all_predictions
    )

    precision, recall, f1, _ = (
        precision_recall_fscore_support(
            all_labels,
            all_predictions,
            average="macro",
            zero_division=0
        )
    )

    return {
        "loss": average_loss,
        "accuracy": accuracy,
        "macro_precision": precision,
        "macro_recall": recall,
        "macro_f1": f1
    }


print("Training function defined.")
print("Validation function defined.")
print("Metrics: Accuracy, Macro Precision, Macro Recall, Macro-F1")
print("Gradient clipping: max_norm = 1.0")
print("\nCell 8 verification PASSED.")

