import os
import glob
import pandas as pd
import numpy as np

def normalize_name(x):
    return str(x).strip().lower().replace("_", " ").replace("-", " ")

def find_metric_value(df, possible_names):

    normalized_columns = {
        normalize_name(c): c for c in df.columns
    }

    for name in possible_names:
        key = normalize_name(name)

        if key in normalized_columns:
            col = normalized_columns[key]

            values = df[col].dropna()

            if len(values) > 0:
                value = values.iloc[0]

                try:
                    return float(value)
                except:
                    return value

    # Check rows where first column may contain metric names
    for col in df.columns:
        series = df[col].astype(str).str.lower()

        for name in possible_names:
            matches = series.str.contains(
                normalize_name(name),
                regex=False,
                na=False
            )

            if matches.any():
                row = df.loc[matches].iloc[0]

                for other_col in df.columns:
                    if other_col != col:
                        try:
                            value = float(row[other_col])
                            return value
                        except:
                            pass

    return np.nan


# ------------------------------------------------------------
# Model-specific file patterns
# ------------------------------------------------------------

model_patterns = {
    "AfroXLM-R": [
        "*afroxlmr*final*metrics*.csv",
        "*afroxlmr*overall*metrics*.csv",
        "*afroxlmr*final*test*.csv"
    ],
    "XLM-R": [
        "*xlmr*final*metrics*.csv",
        "*xlmr*final*test*.csv"
    ],
    "mBERT": [
        "*mbert*final*metrics*.csv",
        "*mbert*final*test*.csv",
        "*mbert*test*metrics*.csv"
    ],
    "BiLSTM": [
        "*bilstm*final*metrics*.csv",
        "*bilstm*final*test*.csv",
        "*bilstm*test*performance*.csv"
    ],
    "TF-IDF + SVM": [
        "*tfidf*svm*final*metrics*.csv",
        "*tfidf*svm*final*test*.csv",
        "*svm*final*metrics*.csv"
    ]
}

metric_names = {
    "Accuracy": [
        "accuracy",
        "test accuracy"
    ],
    "Macro Precision": [
        "macro precision",
        "macro-precision",
        "macro_precision"
    ],
    "Macro Recall": [
        "macro recall",
        "macro-recall",
        "macro_recall"
    ],
    "Macro F1": [
        "macro f1",
        "macro-f1",
        "macro_f1"
    ],
    "Weighted Precision": [
        "weighted precision",
        "weighted-precision",
        "weighted_precision"
    ],
    "Weighted Recall": [
        "weighted recall",
        "weighted-recall",
        "weighted_recall"
    ],
    "Weighted F1": [
        "weighted f1",
        "weighted-f1",
        "weighted_f1"
    ],
    "Correct": [
        "correct",
        "correct predictions"
    ],
    "Incorrect": [
        "incorrect",
        "incorrect predictions"
    ],
    "Total": [
        "total",
        "test total",
        "total test"
    ]
}


# ------------------------------------------------------------
# Search files
# ------------------------------------------------------------

all_csvs = glob.glob("/content/**/*.csv", recursive=True)

final_rows = []

for model, patterns in model_patterns.items():

    matched = []

    for pattern in patterns:
        matched.extend(
            glob.glob("/content/**/" + pattern, recursive=True)
        )

    matched = sorted(set(matched))

    print("\n" + "=" * 100)
    print(model)
    print("=" * 100)

    if not matched:
        print("No matching result file found.")
        continue

    for path in matched:
        print("\nUsing:", path)

        try:
            df = pd.read_csv(path)
        except Exception as e:
            print("Read error:", e)
            continue

        row = {"Model": model}

        for metric, names in metric_names.items():
            row[metric] = find_metric_value(df, names)

        # Check whether this looks like a useful metric file
        available = sum(
            pd.notna(row[m])
            for m in [
                "Accuracy",
                "Macro Precision",
                "Macro Recall",
                "Macro F1",
                "Weighted F1"
            ]
        )

        if available >= 2:
            final_rows.append(row)

            print("\nExtracted:")
            for k, v in row.items():
                print(f"{k}: {v}")

            break


# ------------------------------------------------------------
# Build final table
# ------------------------------------------------------------

overall_final_df = pd.DataFrame(final_rows)

# ------------------------------------------------------------
# Add verified current AfroXLM-R and XLM-R results
# if they are not found automatically
# ------------------------------------------------------------

if "Model" not in overall_final_df.columns:
    overall_final_df = pd.DataFrame(
        columns=[
            "Model",
            "Accuracy",
            "Macro Precision",
            "Macro Recall",
            "Macro F1",
            "Weighted Precision",
            "Weighted Recall",
            "Weighted F1",
            "Correct",
            "Incorrect",
            "Total"
        ]
    )

# Remove possible duplicates
overall_final_df = overall_final_df.drop_duplicates(
    subset=["Model"],
    keep="first"
)

# ------------------------------------------------------------
# Display
# ------------------------------------------------------------

print("\n" + "=" * 120)
print("FINAL EXTRACTED MODEL PERFORMANCE")
print("=" * 120)

display(overall_final_df)

# ------------------------------------------------------------
# Save
# ------------------------------------------------------------

overall_final_df.to_csv(
    "/content/FINAL_ALL_MODEL_PERFORMANCE.csv",
    index=False
)

print("\nSaved:")
print("/content/FINAL_ALL_MODEL_PERFORMANCE.csv")

