import os
import re
import pandas as pd
import numpy as np


# ============================================================
# 1. LOAD VERIFIED DATASET
# ============================================================

DATA_PATH = "/content/amharic_intention_dataset.csv"

if not os.path.exists(DATA_PATH):
    raise FileNotFoundError(
        f"Dataset not found:\n{DATA_PATH}"
    )

df = pd.read_csv(DATA_PATH)

print("=" * 90)
print("TAXONOMY AND ANNOTATION-DIMENSION VERIFICATION")
print("=" * 90)

print("\nDataset shape:")
print(df.shape)

print("\nDataset columns:")
for col in df.columns:
    print(f"  {col}")


# ============================================================
# 2. SEARCH FOR TAXONOMY-RELATED COLUMNS
# ============================================================

column_text = {
    col: str(col).lower().replace("-", "_").replace(" ", "_")
    for col in df.columns
}


keyword_groups = {

    "literal_nonliteral": [
        "literal",
        "nonliteral",
        "non_literal",
        "literal_flag",
        "divergence",
        "surface_meaning"
    ],

    "confidence": [
        "confidence",
        "confidence_score",
        "confidence_rating",
        "rating"
    ],

    "secondary_label": [
        "secondary",
        "secondary_label",
        "secondary_intention",
        "secondary_intent"
    ],

    "other_none": [
        "other",
        "none",
        "other_none",
        "other_intention",
        "none_intention"
    ],

    "intention": [
        "intention",
        "intent",
        "label"
    ]
}


detected_columns = {}

for category, keywords in keyword_groups.items():

    matches = []

    for original, normalized in column_text.items():

        for keyword in keywords:

            if keyword in normalized:
                matches.append(original)
                break

    detected_columns[category] = sorted(
        list(set(matches))
    )


# ============================================================
# 3. DISPLAY DETECTED FIELDS
# ============================================================

print("\n" + "=" * 90)
print("TAXONOMY-RELATED FIELDS DETECTED")
print("=" * 90)

for category, columns in detected_columns.items():

    print(f"\n{category}:")

    if columns:

        for col in columns:
            print(f"  {col}")

    else:

        print("  None detected")


# ============================================================
# 4. VERIFY FINAL INTENTION LABELS
# ============================================================

label_col = None

for candidate in [
    "label",
    "intention",
    "intent",
    "label_name",
    "class"
]:

    if candidate in df.columns:
        label_col = candidate
        break


print("\n" + "=" * 90)
print("FINAL INTENTION LABEL VERIFICATION")
print("=" * 90)

if label_col is None:

    print("No intention-label column was detected.")

else:

    print(
        f"Label column: {label_col}"
    )

    label_counts = (
        df[label_col]
        .fillna("<MISSING>")
        .astype(str)
        .value_counts()
        .sort_index()
    )

    label_distribution = pd.DataFrame({

        "label": label_counts.index,

        "count": label_counts.values,

        "percentage": (
            label_counts.values /
            len(df) *
            100
        )
    })

    display(
        label_distribution
    )


# ============================================================
# 5. CHECK FOR OTHER/NONE CATEGORY
# ============================================================

print("\n" + "=" * 90)
print("OTHER / NONE CATEGORY CHECK")
print("=" * 90)

other_none_rows = pd.DataFrame()

if label_col is not None:

    label_strings = (
        df[label_col]
        .fillna("")
        .astype(str)
        .str.strip()
        .str.lower()
    )

    other_mask = (
        label_strings.isin([
            "other",
            "others",
            "none",
            "none of the above",
            "other/none",
            "other_none"
        ])
    )

    other_none_rows = df.loc[
        other_mask
    ].copy()

    print(
        "OTHER/NONE instances:",
        len(other_none_rows)
    )

    if len(other_none_rows) > 0:

        print(
            "\nDetected OTHER/NONE labels:"
        )

        print(
            df.loc[
                other_mask,
                label_col
            ].value_counts()
        )

    else:

        print(
            "No explicit OTHER/NONE category "
            "was found in the final label column."
        )


# ============================================================
# 6. ANALYZE LITERAL/NON-LITERAL FIELD
# ============================================================

literal_columns = detected_columns[
    "literal_nonliteral"
]

literal_distribution_records = []

print("\n" + "=" * 90)
print("LITERAL / NON-LITERAL ANALYSIS")
print("=" * 90)

if literal_columns:

    for col in literal_columns:

        print(
            f"\nField: {col}"
        )

        counts = (
            df[col]
            .fillna("<MISSING>")
            .astype(str)
            .str.strip()
            .value_counts(dropna=False)
        )

        display(
            counts.to_frame(
                "count"
            )
        )

        for value, count in counts.items():

            literal_distribution_records.append({

                "field": col,

                "value": value,

                "count": int(count),

                "percentage": (
                    count /
                    len(df) *
                    100
                )
            })

else:

    print(
        "No literal/non-literal field was detected."
    )


# ============================================================
# 7. ANALYZE CONFIDENCE FIELD
# ============================================================

confidence_columns = detected_columns[
    "confidence"
]

confidence_records = []

print("\n" + "=" * 90)
print("CONFIDENCE FIELD ANALYSIS")
print("=" * 90)

if confidence_columns:

    for col in confidence_columns:

        print(
            f"\nField: {col}"
        )

        print(
            "Data type:",
            df[col].dtype
        )

        print(
            "Missing values:",
            int(df[col].isna().sum())
        )

        numeric_values = pd.to_numeric(
            df[col],
            errors="coerce"
        )

        if numeric_values.notna().sum() > 0:

            print(
                "\nNumeric summary:"
            )

            display(
                numeric_values.describe()
                .to_frame("value")
            )

        else:

            print(
                "\nValue distribution:"
            )

            display(
                df[col]
                .fillna("<MISSING>")
                .astype(str)
                .value_counts(
                    dropna=False
                )
                .to_frame("count")
            )

else:

    print(
        "No confidence field was detected."
    )


# ============================================================
# 8. ANALYZE SECONDARY LABELS
# ============================================================

secondary_columns = detected_columns[
    "secondary_label"
]

secondary_records = []

print("\n" + "=" * 90)
print("SECONDARY LABEL ANALYSIS")
print("=" * 90)

if secondary_columns:

    for col in secondary_columns:

        print(
            f"\nField: {col}"
        )

        print(
            "Missing values:",
            int(df[col].isna().sum())
        )

        counts = (
            df[col]
            .fillna("<MISSING>")
            .astype(str)
            .str.strip()
            .value_counts(dropna=False)
        )

        display(
            counts.to_frame("count")
        )

        for value, count in counts.items():

            secondary_records.append({

                "field": col,

                "value": value,

                "count": int(count),

                "percentage": (
                    count /
                    len(df) *
                    100
                )
            })

else:

    print(
        "No secondary-label field was detected."
    )


# ============================================================
# 9. CHECK ALL COLUMNS FOR UNUSED ANNOTATION DIMENSIONS
# ============================================================

print("\n" + "=" * 90)
print("POSSIBLE ANNOTATION / TAXONOMY FIELDS")
print("=" * 90)

annotation_keywords = [
    "annot",
    "intent",
    "intention",
    "literal",
    "confidence",
    "secondary",
    "primary",
    "force",
    "direct",
    "indirect",
    "irony",
    "sarcasm",
    "pragmatic"
]

possible_annotation_columns = []

for col in df.columns:

    normalized = column_text[col]

    if any(
        keyword in normalized
        for keyword in annotation_keywords
    ):

        possible_annotation_columns.append(
            col
        )


for col in possible_annotation_columns:

    print(
        f"\n{col}"
    )

    print(
        "  dtype:",
        df[col].dtype
    )

    print(
        "  unique values:",
        df[col].nunique(dropna=False)
    )

    print(
        "  missing:",
        int(df[col].isna().sum())
    )


# ============================================================
# 10. CHECK WHETHER ONLY THE PRIMARY LABEL ENTERED MODELING
# ============================================================

modeling_columns = [
    "text",
    "label",
    "label_id"
]

available_modeling_columns = [
    col for col in modeling_columns
    if col in df.columns
]

print("\n" + "=" * 90)
print("FINAL MODELING INPUT FIELD CHECK")
print("=" * 90)

print(
    "Dataset fields available for the primary classification task:"
)

for col in available_modeling_columns:

    print(
        f"  {col}"
    )


additional_annotation_fields = [
    col
    for col in possible_annotation_columns
    if col not in available_modeling_columns
]

print(
    "\nAdditional annotation-related fields:"
)

if additional_annotation_fields:

    for col in additional_annotation_fields:
        print(
            f"  {col}"
        )

else:

    print(
        "None detected."
    )


# ============================================================
# 11. CREATE TAXONOMY VERIFICATION SUMMARY
# ============================================================

summary_rows = [

    {
        "item":
            "Total dataset instances",

        "result":
            len(df)
    },

    {
        "item":
            "Primary label column",

        "result":
            label_col
            if label_col is not None
            else "Not detected"
    },

    {
        "item":
            "Number of primary labels",

        "result":
            (
                df[label_col].nunique(
                    dropna=True
                )
                if label_col is not None
                else None
            )
    },

    {
        "item":
            "Literal/non-literal field detected",

        "result":
            "Yes"
            if literal_columns
            else "No"
    },

    {
        "item":
            "Confidence field detected",

        "result":
            "Yes"
            if confidence_columns
            else "No"
    },

    {
        "item":
            "Secondary-label field detected",

        "result":
            "Yes"
            if secondary_columns
            else "No"
    },

    {
        "item":
            "Explicit OTHER/NONE category",

        "result":
            "Yes"
            if len(other_none_rows) > 0
            else "No"
    },

    {
        "item":
            "Additional annotation fields detected",

        "result":
            ", ".join(
                additional_annotation_fields
            )
            if additional_annotation_fields
            else "None"
    }
]


taxonomy_summary = pd.DataFrame(
    summary_rows
)


# ============================================================
# 12. SAVE RESULTS
# ============================================================

summary_path = (
    "/content/intention_taxonomy_verification_summary.csv"
)

taxonomy_summary.to_csv(
    summary_path,
    index=False
)


if literal_distribution_records:

    literal_path = (
        "/content/intention_literal_nonliteral_distribution.csv"
    )

    pd.DataFrame(
        literal_distribution_records
    ).to_csv(
        literal_path,
        index=False
    )


if secondary_records:

    secondary_path = (
        "/content/intention_secondary_label_distribution.csv"
    )

    pd.DataFrame(
        secondary_records
    ).to_csv(
        secondary_path,
        index=False
    )


# ============================================================
# 13. FINAL SUMMARY
# ============================================================

print("\n" + "=" * 90)
print("FINAL TAXONOMY VERIFICATION SUMMARY")
print("=" * 90)

display(
    taxonomy_summary
)

print(
    "\nSaved:"
)

print(
    summary_path
)

if literal_distribution_records:

    print(
        literal_path
    )

if secondary_records:

    print(
        secondary_path
    )


print("\nCell 35 completed successfully.")